window.EXCEL_CRITERIA = [{"id":1,"number":"1.1.1","title":"Terdapat kebijakan K3 yang tertulis, bertanggal, ditandatangani oleh pengusaha atau pengurus, secara jelas menyatakan tujuan dan sasaran K3 serta komitmen terhadap peningkatan K3","explanation":"Perusahaan membuat kebijakan K3 secara tertulis, bertanggal, isinya mencakup tujuan dan sasaran K3 serta pernyataan tertulis komitmen perusahaan mengenai pelaksanaan K3 di tempat kerjanya","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"KEBIJAKAN KESELAMATAN DAN KESEHATAN KERJA"},{"id":2,"number":"1.1.2","title":"Kebijakan disusun oleh pengusaha dan/atau pengurus setelah melalui proses konsultasi dengan wakil tenaga kerja","explanation":"Proses konsultasi bisa dalam bentuk rapat yang membahas perumusan isi kebijakan dimana peserta rapat dapat berasal dari anggota P2K3 (wakil tenaga kerja)/wakil departemen dan atau serikat pekerja. Proses konsultasi komunikasi dapat dilihat pada notulensi rapat pembahasan kebijakan ini.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"KEBIJAKAN KESELAMATAN DAN KESEHATAN KERJA"},{"id":3,"number":"1.1.3","title":"Perusahaan mengkomunikasikan kebijakan K3 kepada seluruh tenaga kerja, tamu, kontraktor, pelanggan, dan pemasok dengan tata cara yang tepat.","explanation":"Bentuk komunikasi kebijakan ini dapat melalui: penempelan poster, pembacaan saat briefing pagi, kartu pengenal visitor, lampiran dalam kontrak, materi briefing bagi tamu, papan pengumuman di pintu masuk, pelatihan pengenalan (induction training) dll.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"KEBIJAKAN KESELAMATAN DAN KESEHATAN KERJA"},{"id":4,"number":"1.1.4","title":"Kebijakan khusus dibuat untuk masalah K3 yang bersifat khusus.","explanation":"Kebijakan K3 khusus dibuat sesuai kondisi tingkat resiko perusahaan atau terkait dengan lintas departemen (tidak wajib harus ada), contoh kebijakan mengenai penggunaan bahan peledak, radiasi, alcohol & drug, dll.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"KEBIJAKAN KESELAMATAN DAN KESEHATAN KERJA"},{"id":5,"number":"1.1.5","title":"Kebijakan K3 dan kebijakan khusus lainnya ditinjau ulang secara berkala untuk\nmenjamin bahwa kebijakan tersebut sesuai dengan perubahan yang terjadi dalam perusahaan dan dalam peraturan perundangundangan","explanation":"Ada mekanisme untuk meninjau ulang isi kebijakan secara berkala misal melalui rapat management review meeting tahunan, rapat P2K3 atau rapat lainnya. Bila ada perubahan nama perusahaan, manajemen, visi, dll. maka kebijakan juga harus direvisi. Jadwal waktu tinjauan ulang sebaiknya dicantumkan dalam dokumen kebijakan.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"KEBIJAKAN KESELAMATAN DAN KESEHATAN KERJA"},{"id":6,"number":"1.2.1","title":"Tanggung jawab dan wewenang untuk mengambil tindakan dan melaporkan kepada semua pihak yang terkait dalam perusahaan di bidang K3 telah ditetapkan, diinformasikan dan didokumentasikan","explanation":"Ada dokumen yang menjelaskan tanggung jawab dan wewenang seseorang yang disahkan oleh pengurus perusahaan, seperti dalam hal ini penunjukan ahli K3 untuk mengambil tindakan dan melapor mengenai K3, salah satu bentuk dokumen yaitu Job description/tanggung jawab K3 yang tertuang dalam manual K3, dll. \nHarus dipastikan personil yang terkait mengetahui hal ini.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TANGGUNG JAWAB DAN WEWENANG UNTUK BERTINDAK"},{"id":7,"number":"1.2.2","title":"Penunjukan penanggung jawab K3 harus sesuai peraturan perundang-undangan","explanation":"Ada beberapa penanggung jawab K3 yang sesuai dengan peraturan perundangan yaitu:","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TANGGUNG JAWAB DAN WEWENANG UNTUK BERTINDAK"},{"id":8,"number":"1.2.3","title":"Pimpinan unit kerja dalam suatu perusahaan bertanggung jawab atas kinerja K3 pada unit kerjanya.","explanation":"Dapat dilihat dalam job description-nya, bukti keterlibatan misalnya dalam penilaian kinerja K3 unit, keterlibatan dalam inspeksi K3, keterlibatan dalam rapat K3 dan memantau pencapaian kinerja unit dibidang K3.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TANGGUNG JAWAB DAN WEWENANG UNTUK BERTINDAK"},{"id":9,"number":"1.2.4","title":"Pengusaha atau Pengurus bertanggung jawab secara penuh untuk menjamin pelaksanaan SMK3.","explanation":"Dapat dilihat dalam Visi, Misi dan Program K3 yang ditetapkan oleh pengusaha atau pengurus perusahaan serta dukungan SDM dan anggaran.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TANGGUNG JAWAB DAN WEWENANG UNTUK BERTINDAK"},{"id":10,"number":"1.2.5","title":"Petugas yang bertanggung jawab untuk penanganan keadaan darurat telah ditetapkan dan mendapatkan pelatihan.","explanation":"Dapat dilihat dari sertifikat pelatihan, dokumentasi latihan darurat, absensi latihan.  Penetapan petugas dapat diketahui dari tanda pengenal misalnya topi/helm khusus, bage, warna baju, dll.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TANGGUNG JAWAB DAN WEWENANG UNTUK BERTINDAK"},{"id":11,"number":"1.2.6","title":"Perusahaan mendapatkan Saran-saran dari para ahli di bidang K3 yang berasal dari dalam dan/atau luar perusahaan.","explanation":"Dari dalam dapat berupa: laporan auditor internal K3, laporan inspeksi ahli K3, laporan studi banding/bench marking, dll.\nDari luar dapat berupa: laporan kinerja K3 dari konsultan independen, nota pemeriksaan dari pegawai pengawas Disnaker setempat.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TANGGUNG JAWAB DAN WEWENANG UNTUK BERTINDAK"},{"id":12,"number":"1.2.7","title":"Kinerja K3 termuat dalam laporan tahunan perusahaan atau laporan lain yang setingkat.","explanation":"Kinerja K3 misalnya: angka kecelakaan (FR/SR), jumlah klaim kecelakaan, prestasi/penghargaan K3, % pencapaian target, lost time injury (LTI), dll.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TANGGUNG JAWAB DAN WEWENANG UNTUK BERTINDAK"},{"id":13,"number":"1.3.1","title":"Tinjauan terhadap penerapan SMK3 meliputi kebijakan, perencanaan, pelaksanaan, pemantauan dan evaluasi telah dilakukan, dicatat dan didokumentasikan","explanation":"Kegiatan tinjauan ulang ini dalam bentuk rapat tinjauan ulang manajemen yang agendanya sesuai dengan lampiran 1 PP No.50  Tahun 2012. Rapat tinjauan manajemen ini dihadiri oleh pimpinan perusahaan dan top manajemen. Rapat tinjauan ulang kebijakan SMK3 tidak dapat disamakan dengan rapat bulanan P2K3.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":14,"number":"1.3.2","title":"Hasil tinjauan dimasukkan dalam perencanaan tindakan manajemen.","explanation":"Lihat pada notulensi rapat tinjauan manajemen bentuk tindakan perbaikan atau corrective action yang akan dilakukan apakah masuk dalam program kerja tahun berikutnya.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":15,"number":"1.3.3","title":"Pengurus harus meninjau ulang pelaksanaan SMK3 secara berkala untuk menilai kesesuaian dan efektivitas SMK3.","explanation":"Kegiatan tinjauan ulang ini dalam bentuk rapat yang dihadiri oleh top manajemen, dan tidak dapat disamakan dengan rapat bulanan P2K3 dan menilai kesesuaian dan efektivitas SMK3. Lihat notulensi rapat dan absensi kehadiran rapat.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":16,"number":"1.4.1","title":"Keterlibatan dan penjadwalan konsultasi tenaga kerja dengan wakil perusahaan didokumentasikan dan disebarluaskan ke seluruh tenaga kerja.","explanation":"Ada dokumentasi tentang kegiatan konsultasi antara tenaga kerja (bukan wakil tenaga kerja) dan wakil perusahaan, contohnya bisa dalam forum serikat pekerja yang salah satu agendanya mengenai K3 atau forum P2K3 antara tenaga kerja dengan wakil pengurus perusahaan/manajemen yang duduk dalam kepengurusan P2K3. Dokumentasi dapat dalam bentuk notulensi kegiatan, jadwal atau time table kegiatan. Wakil perusahaan adalah personil yang ditunjuk oleh manajemen perusahaan (MR).","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":17,"number":"1.4.2","title":"Terdapat prosedur yang memudahkan konsultasi mengenai perubahan-perubahan yang mempunyai implikasi terhadap K3.","explanation":"Prosedur tersebut dapat berupa pedoman atau tata cara atau tahapan penyampaian masalah/ issue K3 dapat berupa formulir isian yang mudah dan sederhana (simple) untuk melaporkan akibat perubahan di tempat kerja perusahaan seperti cara kerja, alat dan bahan yang dirasa pekerja membahayakan dirinya.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":18,"number":"1.4.3","title":"Perusahaan telah membentuk P2K3 Sesuai dengan peraturan perundang-undangan.","explanation":"Buktinya dapat berupa dokumen surat penunjukan/pengesahan P2K3 dari Disnaker setempat.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":19,"number":"1.4.4","title":"Ketua P2K3 adalah pimpinan puncak atau pengurus.","explanation":"Lihat pada dokumen 1.4.3 siapa yang menjabat sebagai ketua P2K3. Seharusnya pengurus atau pimpinan puncak perusahaan, yang dimaksud pengurus disini sesuai dengan Pemenaker No.Per.04/ MEN/1987 pasal 3 ayat (1)","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":20,"number":"1.4.5","title":"Sekretaris P2K3 adalah ahli K3 sesuai dengan peraturan perundang-undangan.","explanation":"Sekretaris P2K3 adalah Ahli K3 sesuai dengan Permanaker No.Per.04/MEN/1987 pasal 3 ayat (2) dan lihat pada surat penunjukan ahli K3 dan sertifikat pelatihan (ahli K3 umum).","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":21,"number":"1.4.6","title":"P2K3 menitikberatkan kegiatan pada pengembangan kebijakan dan prosedur mengendalikan risiko.","explanation":"Lihat pada program-program K3 yang direncanakan atau sedang dilaksanakan oleh P2K3 selama ini, apakah ada program mengenai pengembangan atau peninjauan kebijakan dan perbaikan/pengembangan prosedur terkait dengan pengendalian risiko terkait temuan dari hasil penilaian risiko (notulen rapat) sesuai dengan tugas dan fungsi P2K3 yang tecantum dalam Permenaker No.Per.04/MEN/1987.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":22,"number":"1.4.7","title":"Susunan pengurus P2K3 didokumentasikan dan diinformasikan kepada tenaga kerja.","explanation":"Dapat dilihat dari mekanisme pemberitahuan/ pengumuman berkaitan dengan informasi K3 dan jumlah tenaga kerja yang mengetahui kepengurusan P2K3","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":23,"number":"1.4.8","title":"P2K3 mengadakan pertemuan secara teratur dan hasilnya disebarluaskan di tempat kerja.","explanation":"Pertemuan P2K3 minimal dilakukan 1 kali dalam sebulan atau sesuai ketentuan dalam prosedur mengenai P2K3. Perhatikan notulen rapat P2K3 yang selama ini sudah berjalan","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":24,"number":"1.4.9","title":"P2K3 melaporkan kegiatannya secara teratur sesuai dengan peraturan perundangundangan","explanation":"Sesuai Permanaker No.: Per. 04/MEN/1987 tiap 3 bulan sekali kegiatan P2K3 harus dilaporkan ke Disnaker setempat minimal menggunakan format pelaporan yang disediakan sesuai dengan peraturan (distribusi pelaporan & rekaman hasil action plan)","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":25,"number":"1.4.10","title":"Dibentuk kelompok-kelompok kerja dan dipilih dari wakil-wakil tenaga kerja yang ditunjuk sebagai penanggung jawab K3 di tempat kerjanya dan kepadanya diberikan pelatihan sesuai dengan peraturan perundang-undangan.","explanation":"Pembentukan kelompok kerja K3 disesuaikan dengan kondisi di dalam perusahaan terkait dengan efektifitas penerapan SMK3 itu sendiri, khususnya dalam hal pembentukan tim tanggap darurat di setiap unit kerja/departemen dan bila penerapan SMK3 di lokasi terpisah misalnya kegiatan konstruksi.\nPelatihan yang diberikan kepada anggota kelompok kerja K3 terkait dengan kegiatan kelompok masing-masing, misalnya regu kebakaran, resque, P3K, cofined space/gas free sertificate, safety patrole, dll.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":26,"number":"1.4.11","title":"Susunan kelompok-kelompok kerja yang telah terbentuk didokumentasikan dan diinformasikan kepada tenaga kerja.","explanation":"Pembentukan tersebut harus diikuti dengan pengecekan kepada pekerja dengan wawancara apakah mereka mengetahui mengenai struktur kelompok kerja tsb.","section":"PEMBANGUNAN DAN PEMELIHARAAN KOMITMEN","subsection":"TINJAUAN DAN EVALUASI"},{"id":27,"number":"2.1.1","title":"Terdapat prosedur terdokumentasi untuk identifikasi potensi bahaya, penilaian, dan pengendalian risiko K3.","explanation":"Terdapat dokumen tertulis berupa prosedur identifikasi bahaya, penilaian dan pengendalian risiko (manajemen risiko). Lihat detil isi prosedurnya, bagaimana tahapan majemen risiko tersebut ditetapkan. Ada petugas / personil / tim yang melakukan manajemen risiko di tempat kerja..","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"RENCANA STRATEGI K3"},{"id":28,"number":"2.1.2","title":"Identifikasi potensi bahaya, penilaian, dan pengendalian risiko K3 sebagai rencana strategi K3 dilakukan oleh petugas yang berkompeten.","explanation":"Ada petugas/personil/tim yang melakukan manajemen risiko di tempat kerja. Kompetensi dilihat dari trainingnya (sertifikat pelatihan baik internal/eksternal) dan pengalamanan kerjanya dan dilihat dari hasil kerjanya yaitu dokumen risk mangement yang ada sesuai dengan tata cara yang telah ditetapkan melalui prosedur atau acuan terkait.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"RENCANA STRATEGI K3"},{"id":29,"number":"2.1.3","title":"Rencana strategi K3 sekurang-kurangya berdasarkan tinjauan awal, identifikasi potensi bahaya, penilaian, pengendalian risiko, dan peraturan perundang-undangan serta informasi K3 lain baik dari dalam maupun luar perusahaan.","explanation":"Terdapat rencana atau program kegiatan untuk mengendalikan risiko yang diidentifikasi dan perhatikan detail rencana tsb. apakah berkaitan dengan dokumen tinjauan awal, identifikasi bahaya yang dilakukan, pengendalian risiko berdasarkan penilaian yang telah dilakukan sesuai peraturan serta informasi K3 baik dari dalam maupun dari luar perusahaan.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"RENCANA STRATEGI K3"},{"id":30,"number":"2.1.4","title":"Rencana strategi K3 yang telah ditetapkan digunakan untuk mengendalikan risiko K3 dengan menetapkan tujuan dan sasaran yang dapat diukur dan menjadi prioritas serta menyediakan sumber daya.","explanation":"Dilihat pada detail dari rencana/ program K3 yang mencakup tujuan/sasaran, siapa pelaksananya, jangka waktu pelaksanaan, sumber daya (termasuk fasilitas) serta prioritasnya (dilihat dari hasil penilaian manajemen risiko)","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"RENCANA STRATEGI K3"},{"id":31,"number":"2.1.5","title":"Rencana kerja dan rencana khusus yang berkaitan dengan produk, proses, proyek atau tempat kerja tertentu telah dibuat dengan menetapkan tujuan dan sasaran yang dapat diukur, menetapkan waktu pencapaian dan menyediakan sumber daya.","explanation":"Sebenarnya item ini sama dengan 2.1.2. Rencana khusus ini lebih dikaitkan dengan hasil modifikasi/perancangan. \nContoh manajemen program yang berkaitan dengan hasil pengendalian risiko dimana ruang lingkupnya terpisah dari program kerja yang telah tersusun. Biasanya bersifat proyek dengan perencanaan jangka panjang.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"RENCANA STRATEGI K3"},{"id":32,"number":"2.1.6","title":"Sistem Rencana Risiko K3 diselaraskan dengan rencana sistem manajemen perusahaan","explanation":"Rencana atau program kegiatan untuk mengendalikan risiko yang diidentifikasi yang tertuang dalam dokumen berupa program/rencana K3 yang diharmonisasikan secara integral dengan manajemen perusahaan dalam programnya.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"RENCANA STRATEGI K3"},{"id":33,"number":"2.2.1","title":"Manual SMK3 meliputi kebijakan, tujuan, rencana, prosedur K3, instruksi kerja,\nformulir, catatan dan tanggung jawab serta wewenang tanggung jawab K3 untuk semua tingkatan dalam perusahaan","explanation":"Dokumen berupa manual SMK3 atau dokumen level-I  yang mencakup kebijakan, tujuan, rencana kerja, dapat dalam bentuk matrik. Korelasi prosedur K3 serta job desc sesuai struktur organisasi yang ada.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"MANUAL SMK3"},{"id":34,"number":"2.2.2","title":"Terdapat manual khusus yang berkaitan dengan produk, proses, atau tempat kerja tertentu.","explanation":"Dokumen dalam bentuk manual khusus/SOP/WI (misal manual untuk pengelolaan bahan kimia, limbah, ergonomi, penanganan bahan peledak, dll)","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"MANUAL SMK3"},{"id":35,"number":"2.2.3","title":"Manual SMK3 mudah didapat oleh semua personil dalam perusahaan sesuai kebutuhan.","explanation":"Manual disimpan pada lokasi yang mudah diakses oleh personil perusahaan, untuk membuktikannya dapat dilihat dari lembar distribusi manual.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"MANUAL SMK3"},{"id":36,"number":"2.3.1","title":"Terdapat prosedur yang terdokumentasi untuk mengidentifikasi, memperoleh, memelihara dan memahami peraturan perundang-undangan, standar, pedoman teknis, dan persyaratan lain yang relevan dibidang K3 untuk seluruh tenaga kerja di perusahaan.","explanation":"Terdapat petunjuk dan informasi bagi setiap tenaga kerja yang memerlukan berkaitan untuk memperoleh dan memahami peraturan, standar, pedoman teknis dan persyaratan yang relevan dengan K3 untuk memudahkan bagi setiap tenaga kerja guna menerapkan alam pekerjaannya.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"PERATURAN PERUNDANGAN DAN PERSYARATAN LAIN DI BIDANG K3"},{"id":37,"number":"2.3.2","title":"Penanggung jawab untuk memelihara dan mendistribusikan informasi terbaru mengenai peraturan perundangan, standar, pedoman teknis, dan persyaratan lain telah ditetapkan","explanation":"Terdapat personil yang ditunjuk dan diberi tanggung jawab dalam memelihara dan mendistribusikan setiap informasi K3 terbaru untuk sampai kepada setiap tenaga kerja yang memerlukannya.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"PERATURAN PERUNDANGAN DAN PERSYARATAN LAIN DI BIDANG K3"},{"id":38,"number":"2.3.3","title":"Persyaratan pada peraturan perundangundangan, standar, pedoman teknis, dan persyaratan lain yang relevan di bidang K3 dimasukkan pada prosedur-prosedur dan petunjuk-petunjuk kerja.","explanation":"Persyaratan K3 dan persyaratan lain yang relevan baik yang berasal dari peraturan, standar, pedoman teknis dll. dipastikan masuk dalam prosedur dan petunjuk kerja.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"PERATURAN PERUNDANGAN DAN PERSYARATAN LAIN DI BIDANG K3"},{"id":39,"number":"2.3.4","title":"Perubahan pada peraturan perundang-undangan, standar, pedoman teknis, dan persyaratan lain yang relevan di bidang K3 digunakan untuk peninjauan prosedur-prosedur dan petunjuk-petunjuk kerja.","explanation":"Persyaratan K3 dan persyaratan lain yang relevan baik yang berasal dari peraturan, standar, pedoman teknis dll digunakan untuk peninjauan terhadap prosedur dan petunjuk kerja.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"PERATURAN PERUNDANGAN DAN PERSYARATAN LAIN DI BIDANG K3"},{"id":40,"number":"2.4.1","title":"Informasi yang dibutuhkan mengenai kegiatan K3 disebarluaskan secara sistematis kepada seluruh tenaga kerja, tamu, kontraktor, pelanggan, dan pemasok.","explanation":"Bentuknya dapat berupa (tulisan, lisan, tanda) papan pengumuman, foto-foto, poster, label, verbal dalam rapat, briefing/apel, e’mail, dll. Tata caranya dapat dilihat dari prosedur komunikasi.\nAda bagian/personil yang ditunjuk sebagai penanggung jawab.","section":"PEMBUATAN DAN PENDOKUMENTASIAN RENCANA K3","subsection":"PERATURAN PERUNDANGAN DAN PERSYARATAN LAIN DI BIDANG K3"},{"id":41,"number":"3.1.1","title":"Prosedur yang terdokumentasi mempertimbangkan identifikasi potensi bahaya, penilaian, dan pengendalian risiko yang dilakukan pada tahap perancangan dan\nmodifikasi.","explanation":"Terdapat dokumentasi tertulis berupa prosedur perancangan ulang yang didalamnya terdapat identifikasi bahaya dan penilaian risiko (manjemen risiko). Lihat detail isi prosedurnya, bagaimana tahapan manjemen risiko tersebut dimasukan pada tahap perancangan.","section":"PENGENDALIAN PERANCANGAN DAN PENINJAUAN KONTRAK","subsection":"PENGENDALIAN PERANCANGAN"},{"id":42,"number":"3.1.2","title":"Prosedur, instruksi kerja dalam penggunaan produk, pengoperasian mesin dan peralatan, instalasi, pesawat atau proses serta informasi lainnya yang berkaitan dengan K3 telah dikembangkan selama perancangan dan/atau modifikasi.","explanation":"Saat perancangan dilakukan juga telah dibuat instruksi kerja/prosedur khusus untuk produk/sarana/proses yang dirancang atau dimodifikasi berdasarkan rekomendasi dari pengendalian risiko yang telah ditetapkan.","section":"PENGENDALIAN PERANCANGAN DAN PENINJAUAN KONTRAK","subsection":"PENGENDALIAN PERANCANGAN"},{"id":43,"number":"3.1.3","title":"Petugas yang kompeten telah ditentukan untuk melakukan verifikasi bahwa perancangan memenuhi persyaratan keselamatan dan kesehatan kerja yang ditetapkan sebelum penggunaan hasil rancangan.","explanation":"Ada personil yang ditunjuk untuk melakukan verifikasi aspek K3 telah dipenuhi dalam perancangan (lihat dalam tahap prosedur perancangan prasyarat personal yang melakukan perancangan).\nPersonal ini dapat dari internal (misal ahli K3) atau eksternal (misal petugas pengawas K3, dari konsultan atau perusahaan jasa K3 yang ditunjuk/ diakreditasi pemerintah).","section":"PENGENDALIAN PERANCANGAN DAN PENINJAUAN KONTRAK","subsection":"PENGENDALIAN PERANCANGAN"},{"id":44,"number":"3.1.4","title":"Semua perubahan dan modifikasi perancangan yang mempunyai implikasi terhadap keselamatan dan kesehatan kerja diidentifikasikan, didokumentasikan, ditinjau ulang dan disetujui oleh petugas yang berwenang sebelum pelaksanaan.","explanation":"Lihat pada rekaman hasil modifikasi/perancangan berupa catatan atau notulensi review perancangan, cheklist kesesuaian dengan aspek K3, tindakan koreksi bila ada perubahan, tanda tangan pengesahan rancangan oleh petugas sesuai 3.1.3","section":"PENGENDALIAN PERANCANGAN DAN PENINJAUAN KONTRAK","subsection":"PENGENDALIAN PERANCANGAN"},{"id":45,"number":"3.2.1","title":"Prosedur yang terdokumentasi harus mampu mengidentifikasi bahaya dan menilai risiko K3 bagi tenaga kerja, lingkungan, dan masyarakat, dimana prosedur tersebut digunakan pada saat memasok barang dan jasa dalam suatu kontrak.","explanation":"Terdapat prosedur tertulis  yang mencakup proses identifikasi potensi bahaya dan penilaian risiko dilkukan pada kegiatan memasok barang dan jasa dalam suatu kontrak. \nBentuk rekaman dapat berupa hasil manajemen risiko pada aktifitas pemasokan barang dan jasa serta muatan tentang kegiatan tsb. tercakup dalam kontrak.","section":"PENGENDALIAN PERANCANGAN DAN PENINJAUAN KONTRAK","subsection":"PENINJAUAN ULANG KONTRAK"},{"id":46,"number":"3.2.2","title":"Identifikasi bahaya dan penilaian risiko dilakukan pada tinjauan kontrak oleh petugas yang berkompeten.","explanation":"Ada petugas yang ditunjuk bertanggung jawab dan memiliki kualifikasi sesuai peraturan perundangan. Persyaratan personil yang melakukan kegiatan tsb tercakup dan diatur dalam prosedur tsb. (minimal telah mendapat pelatihan ahli k3 dan manajemen risiko yang berpengalaman di bidangnya)","section":"PENGENDALIAN PERANCANGAN DAN PENINJAUAN KONTRAK","subsection":"PENINJAUAN ULANG KONTRAK"},{"id":47,"number":"3.2.3","title":"Kontrak ditinjau ulang untuk menjamin bahwa pemasok dapat memenuhi persyaratan K3 bagi pelanggan","explanation":"Bila 3.2.1 sudah ada dan diterapkan maka kriteria tsb tentunya otomatis akan dipenuhi dan akan terlihat apakah persyaratan K3 dari pelanggan telah terpenuhi. Rekamanan dalam isi kontrak tsb telah memuat aspek K3 di dalamnya secara jelas sesuai dengan spesifikasi pekerjaannya, seperti penyediaan perlengkapan APD, tanggung jawab dan tanggung gugat terhadap kecelakaan, asuransi kecelakaan, dll. Peninjauan ulang kontrak tsb dilakukan secara periodik, khususnya apabila akan dilakukan kontrak baru atau akan dilakukan perubahan kontrak.","section":"PENGENDALIAN PERANCANGAN DAN PENINJAUAN KONTRAK","subsection":"PENINJAUAN ULANG KONTRAK"},{"id":48,"number":"3.2.4","title":"Catatan tinjauan ulang kontrak dipelihara dan didokumentasikan.","explanation":"Dokumentasi catatan tinjauan ulang kontrak berupa cheklist pemenuhan persyaratan K3 dalam suatu kontrak dan catatan perubahannya oleh petugas yang berwenang.","section":"PENGENDALIAN PERANCANGAN DAN PENINJAUAN KONTRAK","subsection":"PENINJAUAN ULANG KONTRAK"},{"id":49,"number":"4.1.1","title":"Dokumen keselamatan dan kesehatan kerja mempunyai identifikasi status, wewenang, tanggal pengeluaran dan tanggal modifikasi.","explanation":"Disini dapat dilihat dari acuan prosedur pengendalian dokumen yang telah ditetapkan, dimana status dokumen dapat berupa tata cara penomoran (kodefikasi dokumen), wewenang dapat berupa siapa personil yang dapat menyetujui dokumen, terdapat tanggal pengeluaran dan modifikasi dokumen bila terjadi perubahan.","section":"PENGENDALIAN DOKUMEN","subsection":"PENINJAUAN ULANG KONTRAK"},{"id":50,"number":"4.1.2","title":"Penerima distribusi dokumen tercantum dalam dokumen tersebut.","explanation":"Dalam dokumen tercantum kepemilikan dokumen tsb dengan mengacu pada daftar distribusi penerima dokumen (holder list)","section":"PENGENDALIAN DOKUMEN","subsection":"PENINJAUAN ULANG KONTRAK"},{"id":51,"number":"4.1.3","title":"Dokumen keselamatan dan kesehatan kerja edisi terbaru disimpan secara sistematis pada tempat yang ditentukan.","explanation":"Dokumen edisi terbaru di unit kerja disimpan pada lokasi tertentu (yang telah ditentukan) dan mudah untuk diakses","section":"PENGENDALIAN DOKUMEN","subsection":"PENINJAUAN ULANG KONTRAK"},{"id":52,"number":"4.1.4","title":"Dokumen usang segera disingkirkan dari penggunaannya sedangkan dokumen usang yang disimpan untuk keperluan tertentu diberi tanda khusus.","explanation":"Perusahaan harus memastikan bahwa dokumen K3 yang sedang beredar adalah dokumen terbaru/revisi terakhir. Bila disimpan maka diberi tanda misalkan “absolute” atau  “superceded” untuk dokumen usang yang masih disimpan. Sekurang-kurangnya disimpan 2 revisi sebelumnya.","section":"PENGENDALIAN DOKUMEN","subsection":"PENINJAUAN ULANG KONTRAK"},{"id":53,"number":"4.2.1","title":"Terdapat sistem untuk membuat dan menyetujui perubahan terhadap dokumen keselamatan dan kesehatan kerja.","explanation":"Terdapat prosedur pengendalian dokumen yang mencakup tahapan proses pembuatan dan persetujuan perubahan dokumen.","section":"PENGENDALIAN DOKUMEN","subsection":"PERUBAHAN DAN MODIFIKASI DOKUMEN"},{"id":54,"number":"4.2.2","title":"Dalam hal terjadi perubahan diberikan alasan terjadinya perubahan dan tertera\ndalam dokumen atau lampirannya dan menginformasikan kepada pihak terkait","explanation":"Pada dokumen yang telah berubah biasanya dilampirkan keterangan/alasan perubahan yang dilakukan, tanggal perubahan/modifikasi dan siapa yang menyetujui perubahan tsb. atau daftar riwayat perubahan, biasanya terletak di depan atau di belakang dokumen tsb. (dalam revision record)","section":"PENGENDALIAN DOKUMEN","subsection":"PERUBAHAN DAN MODIFIKASI DOKUMEN"},{"id":55,"number":"4.2.3","title":"Terdapat prosedur pengendalian dokumen atau daftar seluruh dokumen yang mencantumkan status dari setiap dokumen tersebut, dalam upaya mencegah penggunaan dokumen yang usang.","explanation":"Terdapat prosedur pengendalian dokumen dimana di dalamnya mempersyaratkan pembuatan masterlist dokumen atau suatu daftar yang berisi semua judul dokumen K3 yang digunakan termasuk statusnya (misalkan revisi terakhir beserta tanggal revisinya)","section":"PENGENDALIAN DOKUMEN","subsection":"PERUBAHAN DAN MODIFIKASI DOKUMEN"},{"id":56,"number":"5.1.1","title":"Terdapat prosedur yang terdokumentasi yang dapat menjamin bahwa spesifikasi teknik dan informasi lain yang relevan dengan keselamatan dan kesehatan kerja telah diperiksa sebelum keputusan untuk membeli.","explanation":"Adanya prosedur tertulis mengenai prosedur pembelian barang atau jasa dimana ada spesifikasi K3 dan informasi lain yang terkait dicantumkan dalam salah satu clausul prosedur tsb. secara jelas, misalkan adanya MSDS untuk pembelian bahan kimia, informasi yang relevan untuk pembelian APD dll. \n\nManual dan Prosedur SMK3, prosedur pembelian barang dan jasa.","section":"PEMBELIAN DAN PENGENDALIAN PRODUK","subsection":"PERUBAHAN DAN MODIFIKASI DOKUMEN"},{"id":57,"number":"5.1.2","title":"Spesifikasi pembelian untuk setiap sarana produksi, zat kimia atau jasa harus dilengkapi spesifikasi yang sesuai dengan persyaratan peraturan perundangan dan standar keselamatan dan kesehatan kerja yang berlaku. \nSpesifikasi Formulir. (Nama perusahaan, SKP PJK3, SKP Tenaga Ahli)","explanation":"Kriteria ini merupakan aplikasi dari kriteria 5.1.1 dimana perusahaan dapat menunjukan contoh catatan puschase order yang memasukkan item K3 saat pembeliannya secara jelas.","section":"PEMBELIAN DAN PENGENDALIAN PRODUK","subsection":"PERUBAHAN DAN MODIFIKASI DOKUMEN"},{"id":58,"number":"5.1.3","title":"Konsultasi dengan tenaga kerja yang kompeten pada saat keputusan pembelian, dilakukan untuk menetapkan persyaratan K3 yang dicantumkan dalam spesifikasi pembelian dan diinformasikan kepada tenaga kerja yang menggunakannya.\n\nFormulir notulensi, atau formulir persetujuan","explanation":"Kegiatan konsultasi ini dapat disebutkan dalam isi prosedur 5.1.1 dan ditunjukkan bukti berupa rekaman konsultasi seperti notulensi meeting/input dari pihak pengguna/user kepada pembeli dan atau pengesahan dalam purchasing order.","section":"PEMBELIAN DAN PENGENDALIAN PRODUK","subsection":"PERUBAHAN DAN MODIFIKASI DOKUMEN"},{"id":59,"number":"5.1.4","title":"Kebutuhan pelatihan, pasokan alat pelindung diri dan perubahan terhadap prosedur kerja harus dipertimbangkan sebelum pembelian dan penggunaannya.\n\nTidak setiap pembelian:\ntraining pada pembelian alat, training vendor. \nGas Detector - User (HSE) memberikan training terkait alat kepada operator. daftar hadir, materi, photo2. (pretest-post test)","explanation":"Jenis kebutuhan pelatihan, APD, dll dapat disebutkan dalam prosedur pembelian dan dapat dibuktikan berupa catatan purchasing order yang telah lengkap item K3 nya. Dokumen peninjauan ulang dapat dalam bentuk pengesahan dalam purchasing order atau hasil peninjauan produk atau jasa yang baru sebelum pembelian, misalnya penilaian dalam pembelian APD dll.","section":"PEMBELIAN DAN PENGENDALIAN PRODUK","subsection":"PERUBAHAN DAN MODIFIKASI DOKUMEN"},{"id":60,"number":"5.1.5","title":"Persyaratan K3 dievaluasi dan menjadi pertimbangan dalam seleksi pembelian.\n\nSebelum pembelian Spesifikasi Formulir. (Nama perusahaan, SKP PJK3, SKP Tenaga Ahli)\n\nperaturan perundangan terhadap barang yang kita beli ada kaitannya","explanation":"Dilakukan evaluasi terhadap persyaratan pembelian yang digunakan sebagai pertimbangan dalam seleksi pembelian yang mungkin disebabkan adanya perubahan/persyaratan K3 baru berkaitan dengan barang yang dibeli.","section":"PEMBELIAN DAN PENGENDALIAN PRODUK","subsection":"PERUBAHAN DAN MODIFIKASI DOKUMEN"},{"id":61,"number":"5.2.1","title":"Barang dan jasa yang telah dibeli diperiksa kesesuaiannya dengan spesifikasi pembelian. \n\nBarang: logistik - tanda terima barang. Jumlah, qty, spesifik. - gudang. \n\nJasa: Konstruksi / renovasi, ijin kerja - JSA, terkait peralatan, harus persyaratan hukum (SKP, lisensi), APD sesuai dengan JSA.","explanation":"Dilakukan pemeriksaan terhadap barang dan jasa kesesuaiannya dengan sesifiksi pembelaian yang telah ditetapkan dalam 5.1.1","section":"PEMBELIAN DAN PENGENDALIAN PRODUK","subsection":"PERUBAHAN DAN MODIFIKASI DOKUMEN"},{"id":62,"number":"5.3.1","title":"Barang dan jasa yang dipasok pelanggan, sebelum digunakan terlebih dahulu diidentifikasi potensi bahaya dan dinilai risikonya dan catatan tersebut dipelihara untuk memeriksa prosedur.\n\nJSA - Ijin kerja - BKB (MSDS),","explanation":"Barang dan jasa yang dipasok pelanggan maksudnya adalah barang/jasa yang digunakan/diproses di tempat kerja untuk kemudian setelah selesei dikembalikan lagi kepada pelanggan. Bukti penerapan kegiatan ini bisa dicantumkan dalam prosedur tersendiri atau melalui rekaman kegiatan menajemen risiko seperti yang dilakukan pada 2.1.1","section":"PEMBELIAN DAN PENGENDALIAN PRODUK","subsection":"PENGENDALIAN BARANG DAN JASA YANG DIPASOK PELANGGAN"},{"id":63,"number":"5.4.1","title":"Semua produk yang digunakan dalam proses produksi dapat diidentifikasi di seluruh tahapan produksi dan instalasi, jika terdapat potensi masalah K3.","explanation":"Dapat berupa HIRADC/IBPPR, kegiatan, kolom (bahan yang digunakan). Alat dan bahan dicantumkan pada HIRADC/IBPPR","section":"PEMBELIAN DAN PENGENDALIAN PRODUK","subsection":"PENGENDALIAN BARANG DAN JASA YANG DIPASOK PELANGGAN"},{"id":64,"number":"5.4.2","title":"Terdapat prosedur yang terdokumentasi untuk penelusuran produk yang telah terjual, jika terdapat potensi masalah K3 di dalam penggunaannya.","explanation":"Prosedur penyediaan energi, laporan performa/kinerja ke PLN, dll","section":"PEMBELIAN DAN PENGENDALIAN PRODUK","subsection":"PENGENDALIAN BARANG DAN JASA YANG DIPASOK PELANGGAN"},{"id":65,"number":"6.1.1","title":"Petugas yang kompeten telah mengidentifikasi bahaya, menilai dan mengendalikan risiko yang timbul dari suatu proses kerja.","explanation":"Perusahaan telah menunjuk personil untuk melakukan manajemen risiko. Bukti penerapannya dapat dilihat dari catatan manajemen risiko untuk setiap tahapan proses kerja. Kompetensi petugas ini dapat dilihat dari sertifikat atau catatan pelatihan manajemen risiko, job desc atau wewenangnya atau dari track record pengalaman serta catatan manajemen risiko sesuai dengan tata cara perhitungan yang telah ditetapkan.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SISTEM KERJA"},{"id":66,"number":"6.1.2","title":"Apabila upaya pengendalian risiko diperlukan maka upaya tersebut ditetapkan melalui tingkat pengendalian. (jika risiko tidak diterima/not acceptable, maka dipengendalian risiko melalui hirarki diperlukan)","explanation":"Pengendalian risiko dapat dilihat dari manajemen risiko yang telah dibuat/diusulkan, apakah pengendalian risko yang diambil telah mengikuti tahapan pengendalian seperti eliminasi, substitusi, rekayasa teknik (termasuk isolasi), administrasi control dan APD. Tidak selalu administrasi kontrol dan APD.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SISTEM KERJA"},{"id":67,"number":"6.1.3","title":"Terdapat prosedur atau petunjuk kerja yang terdokumentasi untuk mengendalikan risiko yang teridentifikasi dan dibuat atas dasar masukan dari personil yang kompeten serta tenaga kerja yang terkait dan disahkan oleh orang yang berwenang di perusahaan","explanation":"Terdapat prosedur atau instruksi kerja (WI) secara tertulis yang sudah mempertimbangkan faktor K3 seperti berdasarkan job safety analysis. Terutama prosedur kerja/WI yang dipersyaratkan dalam pengendalian risiko (pengendalian administratif) sebagai pengendalian administrasi kontrol harus dapat ditunjukkan.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SISTEM KERJA"},{"id":68,"number":"6.1.4","title":"Kepatuhan terhadap peraturan perundangundangan, standar serta pedoman teknis yang relevan diperhatikan pada saat mengembangkan atau melakukan modifikasi atau petunjuk kerja.","explanation":"Bila ada pengembangan dan atau perubahan terhadap prosedur kerja/ instruksi kerja maka harus mengacu kepada ketentuan peraturan perundangan, standar atau ketentuan lainnya yang terkait. Biasanya pada prosedur kerja/instruksi kerja dapat ditemukan pada kolom referensi, dimana dalam referensi tsb dicantumkan section standar/peraturan yang dijadikan acuan.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SISTEM KERJA"},{"id":69,"number":"6.1.5","title":"Terdapat sistem izin kerja untuk tugas berisiko tinggi","explanation":"Iziin kerja beresiko tinggi misalnya hot work permit, confined space permit, ketinggian, penggalian/kedalaman, radiasi dll, tergantung dari proses yang ada di tempat kerja.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SISTEM KERJA"},{"id":70,"number":"6.1.6","title":"Alat pelindung diri disediakan sesuai kebutuhan dan digunakan secara benar serta selalu dipelihara dalam kondisi layak pakai.","explanation":"Lihat penerapannya di lapangan, apakah APD disediakan sesuai dengan matriks kebutuhan APD atau yang tercantum dalam prosedur/WI berdasarkan job safety analysisnya ? APD yang disediakan dipakai dengan benar ? Bagaimana kondisinya ? Ambil sampel saja.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SISTEM KERJA"},{"id":71,"number":"6.1.7","title":"Alat pelindung diri yang digunakan dipastikan telah dinyatakan layak pakai\nsesuai dengan standar dan/atau peraturan perundang-undangan yang berlaku.","explanation":"Kesesuaian APD dengan standar/peraturan perundangan yang berlaku dapat dilihat pada spesifikasi teknisnya yang berasal dari pihak supplier yang tercantum dalam informasi brosur maupun sertifikat uji kelayakan dari pihak yang berwenang yang terlampir (setifikasi produk). \nUji kelayakan dapat mengacu kepada beberapa standar yang berlaku secara universal misal SNI, BS, ISO, dll.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SISTEM KERJA"},{"id":72,"number":"6.1.8","title":"Upaya pengendalian risiko dievaluasi secara berkala apabila terjadi ketidaksesuaian atau perubahan pada proses kerja.","explanation":"Terkait dengan 6.1.1 dimana pengendalian risiko yang telah dilaksanakan ditinjau kembali apabila terjadi perubahan pada proses kerja yang ada.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SISTEM KERJA"},{"id":73,"number":"6.2.1","title":"Dilakukan pengawasan untuk menjamin bahwa setiap pekerjaan dilaksanakan dengan aman dan mengikuti setiap prosedur dan petunjuk kerja yang telah ditentukan.","explanation":"Ada kegiatan pengawasan terhadap pelaksanaan pekerjaan di tempat kerja. biasanya menjadi tanggung jawab supervisor atau yang setingkat. Lihat pada uraian tanggung jawabnya. Bukti dokumen dapat berupa catatan/log book inspeksi harian.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"PENGAWASAN"},{"id":74,"number":"6.2.2","title":"Setiap orang diawasi sesuai dengan tingkat kemampuan mereka dan tingkat risiko tugas.","explanation":"Lihat kembali pada uraian tanggung jawab pada 6.2.1 atau adanya kegiatan pemantauan bagi karyawan baru atau program on the job training.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"PENGAWASAN"},{"id":75,"number":"6.2.3","title":"Pengawas/penyelia ikut serta dalam identifikasi bahaya dan membuat upaya pengendalian.","explanation":"Idem dengan 6.2.1 lihat pada job desc nya. Bukti penerapan berupa laporan inspeksi/laporan sumber bahaya atau lainnya.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"PENGAWASAN"},{"id":76,"number":"6.2.4","title":"Pengawas/penyelia diikutsertakan dalam melakukan penyelidikan dan pembuatan laporan terhadap terjadinya kecelakaan dan penyakit akibat kerja serta wajib menyerahkan laporan dan saran-saran kepada pengusaha atau pengurus.","explanation":"Pengawas terlibat dalam kegiatan pelaporan dan penyelidikan kecelakaan dan penyakit akibat kerja. Lihat pada prosedur pelaporan & penyelidikan kecelakaan kerja (eleman 8) dan item pada 6.2.1 (uraian job desc). Lihat juga pada dokumen pelaporan dan hasil penyelidikan kecelakan yang pernah terjadi.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"PENGAWASAN"},{"id":77,"number":"6.2.5","title":"Pengawas/penyelia ikut serta dalam proses konsultasi.","explanation":"Proses konsultasi disini dapat berupa keterlibatan pengawas dalam rapat yang membahas masalah-masalah K3 dalam area pengawasannya.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"PENGAWASAN"},{"id":78,"number":"6.3.1","title":"Persyaratan tugas tertentu termasuk persyaratan kesehatan diidentifikasi dan dipakai untuk menyeleksi dan menempatkan tenaga kerja.","explanation":"Perusahaan menetapkan syarat kesehatan dalam penerimaan pekerja. Lihat pada prosedur penerimaan pekerja dan data-data aktifias pemeriksaan kesehatan tenaga kerja selama ini.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":79,"number":"6.3.2","title":"Penugasan pekerjaan harus berdasarkan kemampuan dan keterampilan serta kewenangan yang dimiliki.","explanation":"Idem dengan 6.3.1 dan terdapat job qualification untuk setiap jabatan yang mencakup menimal pelatihan dan latar belakang pendidikan serta pengalaman.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":80,"number":"6.4.1","title":"Pengusaha atau pengurus melakukan penilaian risiko lingkungan kerja untuk\nmengetahui daerah-daerah yang memerlukan pembatasan izin masuk.","explanation":"Adanya dokumen atau daftar daerah-daerah di tempat kerja yang memerlukan ijin masuk. Dapat juga dicek langsung ke lapangan atau dilihat dari catatan manajemen risiko yang telah dilakukan.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":81,"number":"6.4.2","title":"Terdapat pengendalian atas daerah/tempat dengan pembatasan izin masuk.","explanation":"Pada daerah-daerah tsb dilakukan pengendalian yang dapat berupa ijin tertulis, penguncian, rambu-rambu, dll.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":82,"number":"6.4.3","title":"Tersedianya fasilitas dan layanan di tempat kerja sesuai dengan standar dan pedoman teknis.","explanation":"Fasilitas dalam hal ini yaitu kamar mandi, wastafel, shower, loker/ruangan ganti, mushola, ruang makan, kantin, sarana olah raga, poliklinik, alat bantu kerja seperti tangga, lantai ruang, transportasi, dll.\nLayanan yaitu penyediaan air minum bersih, layanan makan, layanan kesehatan, dll.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":83,"number":"6.4.4","title":"Rambu-rambu K3 harus dipasang sesuai dengan standar dan pedoman teknis.","explanation":"Rambu K3 (safety sign, warning sign, poster, rambu APD, rambu APAR, rambu parkir, dll) dan anda pintu darurat dipasng sesuai standar berdasarkan pedoman teknis yang berlaku, mepunyai sinyal penerangan minimal 10 lux dan berwarna hijau serta tulisan putih dan mempunyai tanda bertuliskan “keluar” atau “exit” di atasnya dan menghadap kekoridor.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":84,"number":"6.5.1","title":"Penjadualan pemeriksaan dan pemeliharaan sarana produksi serta peralatan mencakup verifikasi alat-alat pengaman serta persyaratan yang ditetapkan oleh peraturan perundang-undangan, standar dan pedoman teknis yang relevan.","explanation":"Perusahaan mempunyai dokumen berupa jadwal pemeliharaan sarana produksi yang dipergunakan di tempat kerja mencakup safety device atau alat-alat pengaman. Verifikasi alat pengaman dapat dilihat dari cheklist pemeriksaan masing-masing saran produksi.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":85,"number":"6.5.2","title":"Semua catatan yang memuat data secara rinci dari kegiatan pemeriksaan,\npemeliharaan, perbaikan dan perubahan yang dilakukan atas sarana dan peralatan produksi harus disimpan dan dipelihara.","explanation":"Perusahaan menyimpan catatan-catatan pemeliharaan yang dilakukan, berbentuk daftar riwayat pemeriksaan alat baik dalam bentuk soft copy atau hard copy.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":86,"number":"6.5.3","title":"Sarana dan peralatan produksi memiliki sertifikat yang masih berlaku sesuai dengan persyaratan peraturan perundang-undangan dan standar.","explanation":"Perusahaan memiliki sertifikat (ijin/pengesahan pemakaian) sarana produksi yang masih berlaku. Beberapa sarana produksi tsb antara lain bejana tekanan (Permenaker No.Per.01/MEN/ 1982), pesawat angkat dan angkut (Permenaker No.Per.05/MEN/ 1985), lift (Permenaker No.Per.03/MEN/1999), pesawat uap (UU dan Peraturan Uap 1930). Untuk tepatnya mengacu pada lembar obyek pengawasan dan terdapat jadwal monitoring penjadwalan terhadap peralatan perusahaan yang masuk dalam obyek pengawasan termasuk jadwal kedaluwarsa sertifikat tsb beserta jadwal resertifikat.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":87,"number":"6.5.4","title":"Pemeriksaan, pemeliharaan, perawatan, perbaikan dan setiap perubahan harus dilakukan petugas yang kompeten dan berwenang.","explanation":"Lihat kompetensi personil yang melakukan kegiatan perawatan sarana produksi tsb. (sertifikat, lisensi, pengalaman), jika dilakukan oleh pihak ke-3 dapat menunjukan CV beserta sertifikat pelaksana berdasarkan proposal yang dikirimkan, kemudian dibandingkan dengan laporan/berita acara penyeleseian pekerjaan apakah sama.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":88,"number":"6.5.5","title":"Terdapat prosedur untuk menjamin bahwa Jika terjadi perubahan terhadap sarana dan peralatan produksi, perubahan tersebut harus sesuai dengan persyaratan peraturan perundang-undangan, standar dan pedoman teknis yang relevan.","explanation":"Idem dengan 6.5.3, untuk detailnya dapat dilihat pada isi peraturan perundangannya, atau ditanyakan apakah pernah ada perubahan yang dilakukan.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":89,"number":"6.5.6","title":"Terdapat prosedur permintaan pemeliharaan sarana dan peralatan produksi dengan kondisi K3 yang tidak memenuhi persyaratan dan perlu segera diperbaiki","explanation":"Terdapat prosedur mengenai kegiatan pemeliharaan dan perbaikan sarana produksi, contoh misalnya rekaman work order form, rekaman kegiatan darai awal samapai akhir atau flow activity.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":90,"number":"6.5.7","title":"Terdapat sistem untuk penandaan bagi peralatan yang sudah tidak aman lagi untuk digunakan atau sudah tidak digunakan.","explanation":"Penandaan pada mesin/sarana produksi yang sedang diperbaiki atau rusak ini dapat dituangkan dalam prosedur pemeliharaan yang mencakup lock-out dan tag-out (LOTO) atau prosedur lock-out dan tag-out (LOTO) bila terpisah. Lihat rekaman penandaan yang ada dibandingkan dengan prosedurnya.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":91,"number":"6.5.8","title":"Apabila diperlukan dilakukan penerapan sistem penguncian pengoperasian (lock out system) untuk mencegah agar sarana produksi tidak dihidupkan sebelum saatnya.","explanation":"Terdapat mekanisme penguncian (lihat bentuk/sistem penguncian yang digunakan) terkait dengan prosedur pemeliharaan/ perbaikan atau prosedur lock-out dan tag-out (LOTO) bila terpisah. Rekamannya dapat dilihat pada daftar pelaksanaan lock-out dan dibandingkan dengan prosedurnya","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":92,"number":"6.5.9","title":"Terdapat prosedur yang dapat menjamin keselamatan dan kesehatan tenaga kerja atau orang lain yang berada didekat sarana dan peralatan produksi pada saat proses pemeriksaan, pemeliharaan, perbaikan dan perubahan.","explanation":"Prosedur pengamanan area.\n- Terdapat prosedur yang dapat menjamin\npengaman area yang saat proses pemeriksaan,\npemeliharaan, perbaikan dan perubahan\ndilakukan\n- Dokumen dalam bentuk formulir/checklist yang\ndigunakan","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":93,"number":"6.5.10","title":"Terdapat penanggung jawab untuk menyetujui bahwa sarana dan peralatan produksi telah aman digunakan setelah proses pemeliharaan, perawatan, perbaikan atau perubahan","explanation":"Mengacu pada prosedur permintaan pemeliharaan/perbaikan untuk menjamin sarana yang diperbaiki sudah aman untuk digunakan kembali. Bukti rekamannya adalah work order form yang telah ditandatangani oleh user setelah proses perbaikan selesei dan bentuk pencabutan LOTO dari personil yang berwenang. (persetujuan siap operasi/ serah terima)","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"SELEKSI DAN PENEMPATAN PERSONIL"},{"id":94,"number":"6.6.1","title":"Apabila perusahaan dikontrak untuk menyediakan pelayanan yang tunduk pada standar dan undang-undang keselamatan dan kesehatan kerja, maka perlu disusun prosedur untuk menjamin bahwa pelayanan memenuhi persyaratan. \n\nPelayan SKS Listrik kepada PLN, harus diatur prosedur yang tunduk pada undang-undang K3. \n\nTenaga Ahli,","explanation":"Pelayanan atau jasa disini termasuk dalam perusahaann jasa K3 (PJK3) sesuai dengan Permenaker No.Per.04/MEN/1995 yang meliputi jasa konsultasi K3, jasa fabrikasi, pemeliharaan, reparasi dan instalasi yeknik K3, jasa pemeriksaan dan pengujian teknik, jasa pemeriksaan dan atau pelayanan kesehata kerja, jasa audit K3 dan jasa pembinaan K3. Bila sebagai penyedia jasa tsb maka persyaratannya harus dipenuhi.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"PELAYANAN"},{"id":95,"number":"6.6.2","title":"Apabila perusahaan diberi pelayanan melalui kontrak, dan pelayanan tunduk pada standar dan perundangan keselamatan dan kesehatan kerja, maka perlu disusun prosedur untuk menjamin bahwa pemberian pelayanan memenuhi persyaratan. \n\nKontrak terdapat persyaratan K3. untuk risiko tinggi. \n\nKriteria K3, PO.","explanation":"Jika sebagai pelanggan (6.6.2) maka dapat dilihat pada elemen 5 (pada prosedur pembelian) dimana sudah didetailkan spesifikasi K3 ini dalam pembelian barang dan jasa. Spesifikasi ini dapat berupa surat penujukan PJK3 dari Kemenakertrans RI. Pada 6.6.2 perusahaan diminta memiliki prosedur seleksi dan evaluasi subkontraktor dimana aspek K3 menjadi prasyarat di dalamnya. Bukti rekaman dapat dilihat dari rekaman kegiatan seleksi dan evaluasi.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"PELAYANAN"},{"id":96,"number":"6.7.1","title":"Keadaan darurat yang potensial di dalam dan/atau di luar tempat kerja telah\ndiidentifikasi dan prosedur keadaan darurat telah didokumentasikan dan diinformasikan agar diketahui oleh seluruh orang yang ada di tempat kerja","explanation":"Perusahaan telah mengidentifikasi keadaan darurat yang mungkin terjadi (fire, spill, ledakan, banjir, huru-hara, dll). Hal ini dibuktikan dengan adanya dokumen tertulis berupa prosedur keadaan darurat perusahaan. Lihat potensi keadaan darurat  di dalam prosedur keadaan darurat dan bandingkan dengan kondisi yang ada mengacu pada catatan manajemen risiko.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"KESIAPAN UNTUK MENANGANI KEADAAN DARURAT"},{"id":97,"number":"6.7.2","title":"Penyediaan alat/sarana dan prosedur keadaan darurat berdasarkan hasil\nidentifikasi dan diuji serta ditinjau secara rutin oleh petugas yang berkompeten dan berwenang.","explanation":"Prosedur tsb harus dilakukan simulasi (ada rekaman uji coba) untuk mengatahui sesuai atau efektif diterapkan. Jadwal simulasi paling tidak dilakukan 1x dalam setahun atau mengacu pada frekwensi pelaksanaan dalam prosedur keadaan darurat itu sendiri. Prosedur keadaan darurat dievaluasi/ditinjau ulang oleh petugas yang kompeten (dapat  oleh personil dari bagian K3 atau pihak luar, misal kerja sama dengan Dinas Kebakaran setempat jika berkaitan dengan masalah kebakaran atau konsultan profesional K3. Evaluasi mecakup kesesuain terhadap skenario prosedur, kesiapan peralatan dan target kecepatan dan ketetapan untuk setiap prosedur keadaan darurat.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"KESIAPAN UNTUK MENANGANI KEADAAN DARURAT"},{"id":98,"number":"6.7.3","title":"Tenaga kerja mendapat instruksi dan pelatihan mengenai prosedur keadaan darurat yang sesuai dengan tingkat risiko.","explanation":"Perusahaan telah membuat instruksi keadaan darurat dan telah dikomfirmasikan kepada seluruh tenaga kerja perusahaan dan memberikan pelatihan dalam bentuk evakuasi drill. Bukti rekaman adalah catatan evakuasi drill untuk setiap tenaga kerja mengacu kepada prosedur keadaan darurat yang sesuai dengan tingkat risiko yang ada di perusahaan.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"KESIAPAN UNTUK MENANGANI KEADAAN DARURAT"},{"id":99,"number":"6.7.4","title":"Petugas penanganan keadaan darurat ditetapkan dan diberikan pelatihan khusus serta diinformasikan kepada seluruh orang yang ada di tempat kerja.","explanation":"Khusus petugas darurat telah diberi pelatihan spesifik darurat sesuai dengan peran dan tugasnya (damkar/P3K). Rekaman dapat berupa daftar hadir dan atau sertifikat pelatihan serta catatan pelatihan terkait. Untuk tim kebakaran dapat mengacu pada Kep.Menaker No.Kep.186/MEN/1999.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"KESIAPAN UNTUK MENANGANI KEADAAN DARURAT"},{"id":100,"number":"6.7.5","title":"Instruksi/prosedur keadaan darurat dan hubungan keadaan darurat diperlihatkan secara jelas dan menyolok serta diketahui oleh seluruh tenaga kerja di perusahaan.","explanation":"Verifikasi dilakukan dengan melihat kondisi di lapangan dengan bukti rekaman yaitu instruksi keadaan darurat, peta evakuasi, terdapat arah panah menuju pintu keluar terdekat & aman, menuju titik berkumpul (muster/asembly point) yang terlihat dengan jelas dan terang pada jarak 20m,mempunyai penerangan minimum 10 lux. Instruksi tsb jelas, singkat dan semua tenaga kerja mengetahui dan memahaminya. Dan hubungan keadaan darurat (nomor kontak telpon, tanda exit, tanda pintu darurat, dll)","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"KESIAPAN UNTUK MENANGANI KEADAAN DARURAT"},{"id":101,"number":"6.7.6","title":"Peralatan, dan sistem tanda bahaya keadaan darurat disediakan, diperiksa, diuji dan dipelihara secara berkala sesuai dengan peraturan perundang-undangan, standar dan pedoman teknis yang relevan.","explanation":"Lihat pada catatan-catatan inspeksi, pengujian dan sertifikat hasil pengujian dan laporan maintenance-nya beserta penjadwalannya (rekaman kegiatan hasil pemeriksaan dan pengujian lengkap dengan jadwalnya), seperti pemeriksaan dan pengujian peralatan hydrant, sprinkle, fire ditector, fire alarm, APAR, emergency lamp, emergency shower, breathing apparatus, dll.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"KESIAPAN UNTUK MENANGANI KEADAAN DARURAT"},{"id":102,"number":"6.7.7","title":"Jenis, jumlah, penempatan dan kemudahan untuk mendapatkan alat keadaan darurat telah sesuai dengan peraturan perundangundangan atau standar dan dinilai oleh petugas yang berkompeten dan berwenang.","explanation":"Posisi alat darurat (APAR, hydrant, kotak P3K, dll) jelas dilihat, tidak terhalang dan bertanda yang mudah dipahami oleh tenaga kerja, termasuk ketepatan dalam spesifikasi alat keadaan darurat yang disediakan  berdasarkan potensi bahayanya. Peralatan keadaan darurat sesuai dengan standar/peraturan perundangan yang berlaku dan diperiksa, diuji, dinilai oleh petugas yang kompeten dibidangnya","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"KESIAPAN UNTUK MENANGANI KEADAAN DARURAT"},{"id":103,"number":"6.8.1","title":"Perusahaan telah mengevaluasi alat P3K dan menjamin bahwa sistem P3K yang ada memenuhi peraturan perundang-undangan, standar dan pedoman teknis","explanation":"Ada kegiatan pengecekan terhadap kondisi isi dari kotak P3K, biasanya berupa cheklist tentang kelengkapan obat, jumlah pemakaian, penggantian, dll. Ada kegiatan pengecekan terhadap kondisi isi dari kotak P3K, biasanya berupa cheklist tentang kelengkapan obat, jumlah pemakaian, penggantian, dll.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"P3K"},{"id":104,"number":"6.8.2","title":"Petugas P3K telah dilatih dan ditunjuk sesuai dengan peraturan perundangan-undangan","explanation":"Ada petugas P3K yang ditunjuk pimpinan perusahaan. Petugas tsb dapat dari lingkungan pekerja atau personil medis di klinik. Pelatihan P3K bagi petugas yang ditunjuk sesuai dengan Per.Menaker No.Per.03/MEN/1982 tentang Pelayanan Kesehatan Tenaga Kerja jo. Per. Menakertrans No. Per.15/MEN/VIII/2008 tantang P3K di Tempat Kerja.","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"P3K"},{"id":105,"number":"6.9.1","title":"Prosedur untuk pemulihan kondisi tenaga kerja maupun sarana dan peralatan produksi yang mengalami kerusakan telah ditetapkan dan dapat diterapkan sesegera mungkin setelah terjadinya kecelakaan dan penyakit akibat kerja.","explanation":"Prosedur tanggap darurat","section":"KEAMANAN BEKERJA BERDASARKAN SISTEM MANAJEMEN K3","subsection":"P3K"},{"id":106,"number":"7.1.1","title":"Pemeriksaan/inspeksi terhadap tempat kerja dan cara kerja dilaksanakan secara teratur.","explanation":"Ada jadwal reguler kegiatan inspeksi. Dapat dilihat pada tabel jadwal atau prosedur inspeksi atau dari hasil laporan inspeksi yang telah dilakukan beberapa waktu sebelumnya. Inspeksi cara kerja dapat mengacu kepada job analysis dan inspeksi tempat kerja dapat mengacu kepada housekeeping.","section":"STANDAR PEMANTAUAN","subsection":"PEMERIKSAAN BAHAYA"},{"id":107,"number":"7.1.2","title":"Pemeriksaan/inspeksi dilaksanakan oleh petugas yang berkompeten dan berwenang yang telah memperoleh pelatihan mengenai identifikasi bahaya.","explanation":"Inspeksi dilakukan secara bersama oleh wakil pengurus dan wakil tenaga kerja dengan syarat telah mengikuti pelatihan identifikasi potensi bahaya. Bukti dapat dilihat dari rekaman hasil inspeksi, siapa yang melakukan dan posisinya","section":"STANDAR PEMANTAUAN","subsection":"PEMERIKSAAN BAHAYA"},{"id":108,"number":"7.1.3","title":"Pemeriksaan/inspeksi mencari masukan dari tenaga kerja yang melakukan tugas di tempat yang diperiksa.","explanation":"Inspeksi bukan saja hanya mengacu pada cheklist tetapi juga memberi ruang masukan diluar cheklist. Dapat dilihat dari catatan inspeksi apakah terdapat masukan dari petugas yang melakukan tugas di tempat yang diperiksa.","section":"STANDAR PEMANTAUAN","subsection":"PEMERIKSAAN BAHAYA"},{"id":109,"number":"7.1.4","title":"Daftar periksa (check list) tempat kerja telah disusun untuk digunakan pada saat pemeriksaan/inspeksi.\n\nAlat (terutama) - harus ada IK","explanation":"Dokumen berupa cheklist inspeksi tempat kerja sesuai dengan kondisi tempat kerjanya.","section":"STANDAR PEMANTAUAN","subsection":"PEMERIKSAAN BAHAYA"},{"id":110,"number":"7.1.5","title":"Laporan pemeriksaan/inspeksi berisi rekomendasi untuk tindakan perbaikan dan diajukan kepada pengurus dan P2K3 sesuai dengan kebutuhan.","explanation":"Lihat tembusan/cc laporan inspeksi dengan mengacu pada prosedur inspeksi.","section":"STANDAR PEMANTAUAN","subsection":"PEMERIKSAAN BAHAYA"},{"id":111,"number":"7.1.6","title":"Pengusaha atau pengurus telah menetapkan penanggung jawab untuk pelaksanaan tindakan perbaikan dari hasil laporan pemeriksaan/inspeksi.","explanation":"Follow up action di monitor (pic, close dan tgl)","section":"STANDAR PEMANTAUAN","subsection":"PEMERIKSAAN BAHAYA"},{"id":112,"number":"7.1.7","title":"Tindakan perbaikan dari hasil laporan pemeriksaan/inspeksi dipantau untuk menentukan efektifitasnya.","explanation":"Terdapat catatan monitoring status penyelesaian terhadap tindakan koreksi dari temuan-temuan inspeksi dan kemudian  tindakan perbaikan yang telah dilakukan telah dinilai keefektifannya dalam arti tidak menimbulkan bahaya baru.","section":"STANDAR PEMANTAUAN","subsection":"PEMERIKSAAN BAHAYA"},{"id":113,"number":"7.2.1","title":"Pemantauan/pengukuran lingkungan kerja dilaksanakan secara teratur dan hasilnya didokumentasikan, dipelihara dan digunakan untuk penilaian dan pengendalian risiko.","explanation":"Adanya dokumentasi/laporan hasil pemantauan lingkungan kerja. interval waktu pelaksanaannya disesuaikan dengan ketentuan/ standar yang berlaku, dapat melalui UKL dan UPL.","section":"STANDAR PEMANTAUAN","subsection":"PEMANTAUAN/PENGUKURAN LINGKUNGAN KERJA"},{"id":114,"number":"7.2.2","title":"Pemantauan/pengukuran lingkungan kerja meliputi faktor fisik, kimia, biologi, ergonomi dan psikologi.","explanation":"Lihat laporan hasil pemantauan/monitoring lingkungan kerja:\nPermenaker No. 5 Tahun 2018 tentang K3 Lingkungan Kerja","section":"STANDAR PEMANTAUAN","subsection":"PEMANTAUAN/PENGUKURAN LINGKUNGAN KERJA"},{"id":115,"number":"7.2.3","title":"Pemantauan/pengukuran lingkungan kerja dilakukan oleh petugas atau pihak yang berkompeten dan berwenang dari dalam dan/atau luar perusahaan.","explanation":"Jelas","section":"STANDAR PEMANTAUAN","subsection":"PEMANTAUAN/PENGUKURAN LINGKUNGAN KERJA"},{"id":116,"number":"7.3.1","title":"Terdapat prosedur yang terdokumentasi mengenai identifikasi, kalibrasi, pemeliharaan dan penyimpanan untuk alat pemeriksaan, ukur dan uji mengenai K3","explanation":"Terdapat prosedur tertulis berkaitan dengan identifikasi, kalibrasi, pemeliharaan dan penyimpanan terhadap alat ukur, misalnya noisemeter, luxmeter, gas detector, dll. Bila alat-alat disediakan dari pihak luar, maka penyedia/supplier/kontraktor harus dapat menunjuk -kan hasil pengujiannya. Hal ini dapat diidentifikasi pada saat tahap kontrak dan pembelian jasa ybs.","section":"STANDAR PEMANTAUAN","subsection":"PERALATAN PEMERIKSAAN/INSPEKSI, PENGUKURAN DAN PENGUJIAN"},{"id":117,"number":"7.3.2","title":"Alat dipelihara dan dikalibrasi oleh petugas atau pihak yang berkompeten dan berwenang dari dalam dan/atau luar perusahaan.","explanation":"Lihat kualifikasi petugas yang melakukan kalibrasi alat tsb atau catatan pelatihannya.","section":"STANDAR PEMANTAUAN","subsection":"PERALATAN PEMERIKSAAN/INSPEKSI, PENGUKURAN DAN PENGUJIAN"},{"id":118,"number":"7.4.1","title":"Dilakukan pemantauan kesehatan tenaga kerja yang bekerja pada tempat kerja yang mengandung potensi bahaya tinggi sesuai dengan peraturan perundang-undangan.","explanation":"Ada`kegiatan dan dokumentasinya  (daftar, jadwal, SOP, rekaman pemeriksaan kesehatan) mengenai kegiatan pemantauan kesehaan tenaga kerja, terutama pemeriksaan pemeriksaan kesehatan khusus seperti misalnya pengecekan darah untuk melihat kontaminasi kadar bahan kimia, audiometri untuk kebisingan, rontgen untuk penyakit saluran pernafasan, dll.","section":"STANDAR PEMANTAUAN","subsection":"PEMANTAUAN KESEHATAN TENAGA KERJA"},{"id":119,"number":"7.4.2","title":"Pengusaha atau pengurus telah melaksanakan identifikasi keadaan dimana pemeriksaan kesehatan tenaga kerja perlu dilakukan dan telah melaksanakan sistem untuk membantu pemeriksaan ini.","explanation":"Hasil identifikasi dalam bentuk daftar program pemeriksaan kesehatan pekerja yang dilakukan dan tata cara atau prosedur untuk pemeriksaan kesehatan tenaga kerja ini.","section":"STANDAR PEMANTAUAN","subsection":"PEMANTAUAN KESEHATAN TENAGA KERJA"},{"id":120,"number":"7.4.3","title":"Pemeriksaan kesehatan tenaga kerja dilakukan oleh dokter pemeriksa yang ditunjuk sesuai peraturan perundangundangan.","explanation":"Pemeriksaan kesehatan tenaga kerja dilakukan oleh dokter perusahaan yang sesuai dengan ketentuan Per.Menaker No.Per.01/MEN/1976 tentang Kewajiban Latihan Hyperkes Bagi Dokter Perusahaan dan mandapatkan surat penunjukan dari Direktur Jenderal Pembinaan Pengawasan Ketenagakerjaan sebagaimana pasal 8 UU Keselamatan Kerja.","section":"STANDAR PEMANTAUAN","subsection":"PEMANTAUAN KESEHATAN TENAGA KERJA"},{"id":121,"number":"7.4.4","title":"Perusahaan menyediakan pelayanan kesehatan kerja sesuai peraturan perundangundangan.","explanation":"Detail pelayanan kesehatan yang diberikan mengacu pada Per. Menaker No.Per.03/MEN /1980","section":"STANDAR PEMANTAUAN","subsection":"PEMANTAUAN KESEHATAN TENAGA KERJA"},{"id":122,"number":"7.4.5","title":"Catatan mengenai pemantauan kesehatan tenaga kerja dibuat sesuai dengan peraturan perundang-undangan.","explanation":"Diwajibkan untuk memberikan pelaporan setiap aktifitas pemeriksaan kesehatan tenaga kerja (rekap medis) yang mengacu pada Per.Menaker No.Per.02/MEN /1982","section":"STANDAR PEMANTAUAN","subsection":"PEMANTAUAN KESEHATAN TENAGA KERJA"},{"id":123,"number":"8.1.1","title":"Terdapat prosedur pelaporan bahaya yang berhubungan dengan K3 dan prosedur ini diketahui oleh tenaga kerja.","explanation":"Perusahaan mempunyai prosedur pelaporan sumber bahaya dan tenaga kerja mengetahu cara pelaporannya. Dokumennya  berupa prosedur pelaporan, formulir pelaporan bahaya/ketidaksesuaian.","section":"PELAPORAN DAN PERBAIKAN KEKURANGAN","subsection":"PELAPORAN BAHAYA"},{"id":124,"number":"8.2.1","title":"Terdapat prosedur terdokumentasi yang menjamin bahwa semua kecelakaan kerja, penyakit akibat kerja, kebakaran atau peledakan serta kejadian berbahaya lainnya di tempat kerja dicatat dan dilaporkan sesuai dengan peraturan perundang-undangan.","explanation":"Dokumen berupa prosedur tata cara pelaporan kecelakaan kerja,  penyakit akibat kerja, kebakaran atau peledakan serta kejadian berbahaya lainnya di tempat kerja sesuai dengan Permenaker No.03/MEN/1998 tentang Tata Cara Pelaporan dan Pemeriksaan Kecelakaan  atau yang juga terdapat dalam laporan triwulan P2K3 perusahaan yang dilaporkan dan dikirim ke Disnaker setempat.","section":"PELAPORAN DAN PERBAIKAN KEKURANGAN","subsection":"PELAPORAN KECELAKAAN"},{"id":125,"number":"8.3.1","title":"Tempat kerja/perusahaan mempunyai prosedur pemeriksaan dan pengkajian kecelakaan kerja dan penyakit akibat kerja","explanation":"Dokumen sama dengan 8.2.1 dimana dapat disajikan satu prosedur yaitu pelaporan dan penyelidikan.","section":"PELAPORAN DAN PERBAIKAN KEKURANGAN","subsection":"PENYELIDIKAN KECELAKAAN"},{"id":126,"number":"8.3.2","title":"Pemeriksaan dan pengkajian kecelakaan kerja dilakukan oleh petugas atau Ahli K3 yang ditunjuk sesuai peraturan perundangundangan atau pihak lain yang berkompeten dan berwenang.","explanation":"Perusahaan telah menetapkan personil perusahaan yang akan melakukan penyelidikan kecelakaan. Kompetensi petugas dapat dilihat pada pelatihan atau sertifikat pelatihan yang dimiliki.","section":"PELAPORAN DAN PERBAIKAN KEKURANGAN","subsection":"PENYELIDIKAN KECELAKAAN"},{"id":127,"number":"8.3.3","title":"Laporan pemeriksaan dan pengkajian berisi tentang sebab dan akibat serta\nrekomendasi/saran dan jadwal waktu pelaksanaan usaha perbaikan.","explanation":"Lihat dan cek pada dokumen laporan kecelakaan selama ini, apakah sudah tertera saran dan jadwal perbaikannya.","section":"PELAPORAN DAN PERBAIKAN KEKURANGAN","subsection":"PENYELIDIKAN KECELAKAAN"},{"id":128,"number":"8.3.4","title":"Penanggung jawab untuk melaksanakan tindakan perbaikan atas laporan\npemeriksaan dan pengkajian telah ditetapkan.","explanation":"Lihat pada dokumen laporan kecelakaan siapa penanggung jawab tindakan perbaikan tersebut. Apakah ybs sudah diberi informasi mengenai tanggung jawab tsb.","section":"PELAPORAN DAN PERBAIKAN KEKURANGAN","subsection":"PENYELIDIKAN KECELAKAAN"},{"id":129,"number":"8.3.5","title":"Tindakan perbaikan diinformasikan kepada tenaga kerja yang bekerja di tempat terjadinya kecelakaan.","explanation":"Verifikasi dilakukan dengan melihat proses saat penyelidikan dilakukan, apakah melibatkan tenaga kerja saat mengumpulkan informasi atau saat mendiskusikan tindakan perbaikan yang akan dilakukan? Cross chek dengan pekerja yang terkait atau sertakan tanda tangan pekerja.","section":"PELAPORAN DAN PERBAIKAN KEKURANGAN","subsection":"PENYELIDIKAN KECELAKAAN"},{"id":130,"number":"8.3.6","title":"Pelaksanaan tindakan perbaikan dipantau, didokumentasikan dan diinformasikan ke seluruh tenaga kerja.","explanation":"Perusahaan melakukan verifikasi terhadap tindakan perbaikan yang diusulkan dalam laporan kecelakaan. Bentuknya dapat berupa status laporan (closed) atau paraf pada tindakan perbaikan yang selesei.","section":"PELAPORAN DAN PERBAIKAN KEKURANGAN","subsection":"PENYELIDIKAN KECELAKAAN"},{"id":131,"number":"8.4.1","title":"Terdapat prosedur untuk menangani masalah keselamatan dan kesehatan yang timbul dan sesuai dengan peraturan perundangundangan yang berlaku.\n\nMasalah kecalakaan kerja, masalah kondisi darurat, masalah PAK, - bisa disediakan prosedur yang terkait yang sudah ada.","explanation":"Ada prosedur penyampaian masalah-masalah K3 di tempat kerja. maslah ini dapat berupa hal-hal seperti: lingkungan kerja yang kurang aman, cara  kerja, kesehatan dalam bekerja atau keluhan-keluhan lainnya.","section":"PELAPORAN DAN PERBAIKAN KEKURANGAN","subsection":"PENANGANAN MASALAH"},{"id":132,"number":"9.1.1","title":"Terdapat prosedur untuk mengidentifikasi potensi bahaya dan menilai risiko yang berhubungan dengan penanganan secara manual dan mekanis.","explanation":"Prosedur yang dimaksud yaitu prosedur  manajemen risiko seperti pada 2.1.1 dan 6.1.1 tetapi kriteria ini lebih fokus pada kegiatan penangan bahan secara manual dan mekanis. Bukti penerapannya lihat hasil laporan risk assesment pada kegiatan tsb.","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"PENANGANAN SECARA MANUAL DAN MEKANIS"},{"id":133,"number":"9.1.2","title":"Identifikasi bahaya dan penilaian risiko dilaksanakan oleh petugas yang berkompeten dan berwenang","explanation":"Verifikasi petugas yang melakukan risk assesment.","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"PENANGANAN SECARA MANUAL DAN MEKANIS"},{"id":134,"number":"9.1.3","title":"Pengusaha atau pengurus menerapkan dan meninjau cara pengendalian risiko yang berhubungan dengan penanganan secara manual atau mekanis.","explanation":"Verifikasi kelapangan apakah rekomendasi tindakan pengendalian risiko dari laporan risk assesment diterapkan di tempat kerja. Bukti rekaman yaitu terdapat monitoring dari program kerja dari pengendalian risiko yang diambil.","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"PENANGANAN SECARA MANUAL DAN MEKANIS"},{"id":135,"number":"9.1.4","title":"Terdapat prosedur untuk penanganan bahan meliputi metode pencegahan terhadap kerusakan, tumpahan dan/atau kebocoran","explanation":"Terdapat prosedur tertulis untuk penanganan terhadap kemungkinan kerusakan, tumpahan dan kebocoran (clinker, dll.)","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"PENANGANAN SECARA MANUAL DAN MEKANIS"},{"id":136,"number":"9.2.1","title":"Terdapat prosedur yang menjamin bahwa bahan disimpan dan dipindahkan dengan cara yang aman sesuai dengan peraturan perundang-undangan.","explanation":"Semua kriteria ini dapat ditunjukkan dengan suatu prosedur dan penerapannya mengenai penanganan bahan agar teratur dan rapi dalam penyimpanan (housekeeping), prosedur tersebut mencakup penanganan terhadap sifat bahan khususnya kadaluarsa bahan seperti pengaturan pengeluaran dan pencatatan masa kode bahan, penempatan bahan sesuai dengan sifat bahan, bahan dalam kondisi siap pakai serta bila tidak dipakai akan dibuang dengan cara yang aman bagi lingkungan berikut juga limbahnya dibuang dengan cara yang aman seperti untuk pembuangan limbah oli dipersyaratkan ke penampung yang mempunyai ijin dan limbah cair ke PPLI dan lain-lain.  Bukti pelaksanaan pembuangan dapat dilihat dari manifestnya.","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"SISTEM PENGANGKUTAN, PENYIMPANAN DAN PEMBUANGAN"},{"id":137,"number":"9.2.2","title":"Terdapat prosedur yang menjelaskan persyaratan pengendalian bahan yang dapat rusak atau kadaluarsa.","explanation":"Bahan-bahan yang ditangani sesuai dengan peraturan perundangan seperti penyimpanan bahan peledak, penyimpanan gas-gas dengan tabung atau bejana bertekanan, yang bersifat reaktif flamability dan lain-lain","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"SISTEM PENGANGKUTAN, PENYIMPANAN DAN PEMBUANGAN"},{"id":138,"number":"9.2.3","title":"Terdapat prosedur yang menjamin bahwa bahan dibuang dengan cara yang aman sesuai dengan peraturan perundangundangan","explanation":"Bila tidak dipakai akan dibuang dengan cara yang aman (seperti untuk pembuangan limbah oli dipersyaratkan kepenampung yang mempunyai ijin dan limbah cair ke PPLI), dll.","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"SISTEM PENGANGKUTAN, PENYIMPANAN DAN PEMBUANGAN"},{"id":139,"number":"9.3.1","title":"Perusahaan telah mendokumentasikan dan menerapkan prosedur mengenai\npenyimpanan, penanganan dan pemindahan BKB sesuai dengan persyaratan peraturan perundang-undangan, standar dan pedoman teknis yang relevan.","explanation":"Ada prosedur terulis mengenai kegiatan-kegiatan tsb untuk bahan berbahaya, dapat berupa prosedur atau instruksi kerja terkait dengan penggunaan bahan kimia tsb. Peraturan yang mengatur tentang pengendalian bahan kimia berbahaya yaitu Kep. Menaker No. Kep.187/MEN/1999.","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"PENGENDALIAN BAHAN KIMIA BERBAHAYA (BKB)"},{"id":140,"number":"9.3.2","title":"Terdapat Lembar Data Keselamatan BKB (Material Safety Data Sheets) meliputi\nketerangan mengenai keselamatan bahan sebagaimana diatur pada peraturan\nperundang-undangan dan dengan mudah dapat diperoleh.","explanation":"Lembar data ini dikenal dengan MSDS (material safety data sheet). Seharusnya di tempat kerja mempunyai/menyimpan MSDS ini, dan dapat didapatkan dari pihak suplier bahan kimia (dipersyarat kan pada elemen 5 dalam pembelian bahan). Rekaman MSDS ini harus dapat ditemukan baik di tempat yang menyiman maupun yang menggunakan bahan. MSDS sebaiknya bersifat komunikatif, artinya dimengerti oleh yang membaca (misalnya dalam bahasa Indonesia).","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"PENGENDALIAN BAHAN KIMIA BERBAHAYA (BKB)"},{"id":141,"number":"9.3.3","title":"Terdapat sistem untuk mengidentifikasi dan pemberian label secara jelas pada bahan kimia berbahaya.","explanation":"Ada pelebelan pada wadah bahan kimia, yang penting lebel ini maksudnya diketahui oleh para user/pengguna bahan kimia. Bukti penerapan di lapangan yaitu semua wadah bahan kimia mempunyai lebel yang berisi nama zat, sifat bahaya/rambu bahaya dan tindakan bila keadaan darurat.","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"PENGENDALIAN BAHAN KIMIA BERBAHAYA (BKB)"},{"id":142,"number":"9.3.4","title":"Rambu peringatan bahaya terpasang sesuai dengan persyaratan peraturan perundangundangan dan/atau standar yang relevan.","explanation":"Rambu peringatan ini menjelaskan bahaya dari bahan kimia yang ada di tempat kerja, misalnya rambu sifat bahan tsb seperti flammable, explosive, poison, dll.","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"PENGENDALIAN BAHAN KIMIA BERBAHAYA (BKB)"},{"id":143,"number":"9.3.5","title":"Penanganan BKB dilakukan oleh petugas yang berkompeten dan berwenang","explanation":"Pihak user telah mendapatkan pelatihan mengenai bahaya bahan kimia serta tata cara pemakaian yang aman dari bahan tersebut. Lihat pada catatan pelatihan atau sertifikat pelatihan","section":"PENGELOLAAN MATERIAL DAN PERPINDAHANNYA","subsection":"PENGENDALIAN BAHAN KIMIA BERBAHAYA (BKB)"},{"id":144,"number":"10.1.1","title":"Pengusaha atau pengurus telah mendokumentasikan dan menerapkan\nprosedur pelaksanaan identifikasi, pengumpulan, pengarsipan, pemeliharaan,\npenyimpanan dan penggantian catatan K3.","explanation":"Pengusaha/pengurus telah menetapkan prosedur yang mengatur pengelolaan terhadap catatan-catatan K3 tersebut. Bukti rekamannya yaitu prosedur pengendalian catatan dimana aplikasinya adalah terdapat masterlist catatan K3 yang minimal mencakup masa simpan dan lokasi penyimpanan. Dimana definisi catatan K3 ini berupa formulir K3 yang sudah terisi misal form kecelakaan, inspeksi, NCR audit, dll.","section":"PENGUMPULAN DAN PENGGUNAAN DATA","subsection":"CATATAN K3"},{"id":145,"number":"10.1.2","title":"Peraturan perundang-undangan, standar dan pedoman teknis K3 yang relevan dipelihara pada tempat yang mudah didapat.","explanation":"Tercakup prosedur pengendalian dokumen yaitu mengenai pegendalian dokumen eksternal, dimana  aplikasinya adanya daftar undang-undang, peraturan, standar dan pedoman teknis yang relevan dimana selalu di update, untuk mengetahuinya dapat dilihat dari tanggal penerbitan dan juga pada daftar tsb dicantumkan lokasi penyimpanannya.","section":"PENGUMPULAN DAN PENGGUNAAN DATA","subsection":"CATATAN K3"},{"id":146,"number":"10.1.3","title":"Terdapat prosedur yang menentukan persyaratan untuk menjaga kerahasiaan\ncatatan.","explanation":"Bukti penerapannya dapat dilihat pada prosedur pengendalian catatan apakah terdapat klausul yang mempersyaratkan kerahasiaan catatan, seperti bagaimana prosedur mengaksesnya, menyimpan dan memusnakannya. Contoh catatan yang bersifat rahasia yaitu medical chek up.","section":"PENGUMPULAN DAN PENGGUNAAN DATA","subsection":"CATATAN K3"},{"id":147,"number":"10.1.4","title":"Catatan kompensasi kecelakaan dan rehabilitasi kesehatan tenaga kerja\ndipelihara.","explanation":"Contoh catatan peninjauan ulang dan pemeriksaan misalnya: notulen management review, notulen rapat P2K3, hasil audit, medical record, dll. dengan mengacu pada daftar masa simpan catatan K3 yang tersusun.","section":"PENGUMPULAN DAN PENGGUNAAN DATA","subsection":"CATATAN K3"},{"id":148,"number":"10.2.1","title":"Data K3 yang terbaru dikumpulkan dan dianalisa","explanation":"Data K3 perusahaan dapat berupa: data kecelakaan minimal FR dan SR, medical cost, laporan penyakit akibat kerja, data % hasil inspeksi, data pencapaian kinerja program K3, data pemantauan lingkungan kerja (misal kebisingan, NAB, dll) yang mana semua data tsb dianalisa.\nTabel, matriks atau grafik atau yang lainnya adalah bentuk pengolahan data, sedangkan analisa data mencakup terhadap analisa untuk mencari akar masalah sampai dengan tindakan koreksi maupun pencegahan yang dilakukan.","section":"PENGUMPULAN DAN PENGGUNAAN DATA","subsection":"DATA DAN LAPORAN K3"},{"id":149,"number":"10.2.2","title":"Laporan rutin kinerja K3 dibuat dan disebarluaskan di dalam tempat kerja.","explanation":"Laporan rutin K3 misalnya laporan yang berhubungan dengan kinerja K3 (FR, SR, LTI/LTA, ZA, dll) termasuk di dalamnya monitoring terhadap program K3","section":"PENGUMPULAN DAN PENGGUNAAN DATA","subsection":"DATA DAN LAPORAN K3"},{"id":150,"number":"11.1.1","title":"Audit internal SMK3 yang terjadwal dilaksanakan untuk memeriksa kesesuaian\nkegiatan perencanaan dan untuk menentukan efektifitas kegiatan tersebut.","explanation":"Perusahaan mempunyai jadwal kegiatan audit internal SMK3 dan telah dilaksanakan sesuai jadwal tsb mengacu kepada prosedur audit internal (lihat pada laporan audit internal yang ada). Bukti harus dapa dipastikan 166 dari kriteria telah diaudit dalam setahun. Untuk mengukur efektifitasnya dapat dilihat dari prosentasinya secara kuantitatif.","section":"AUDIT SMK3","subsection":"Audit Internal SMK3"},{"id":151,"number":"11.1.2","title":"Audit internal SMK3 dilakukan oleh petugas yang independen, berkompeten dan\nberwenang.","explanation":"Petugas atau auditor internal SMK3 harus kompeten yakni telah diberikan pelatihan mengenai isi SMK3 dan standar audit SMK3 (lihat pada catatan pelatihan/ sertifikat auditor SMK3 dan penunjukan sebagai auditor internal yang ada). Petugas yang kompeten juga dapat dilahat dari contoh hasil laporan audit internal yang telah dilakukan selama ini.\nIndepeden yakni tidak mengaudit di bagian/unitnya sediri.","section":"AUDIT SMK3","subsection":"Audit Internal SMK3"},{"id":152,"number":"11.1.3","title":"Laporan audit didistribusikan kepada pengusaha atau pengurus dan petugas lain\nyang berkepentingan dan dipantau untuk menjamin dilakukannya tindakan perbaikan.","explanation":"Tiap laporan  hasil audit terdapat daftar distribusi penerimaan dokumen laporan tsb.","section":"AUDIT SMK3","subsection":"Audit Internal SMK3"},{"id":153,"number":"12.1.1","title":"Analisis kebutuhan pelatihan K3 sesuai persyaratan peraturan perundang-undangan telah dilakukan","explanation":"Adanya dokumen training need analysis (TNA) yang mencakup kebutuhan pelatihan K3 (hubungan antara kompetensi K3 dengan pelatihan K3 yang perlu disiapkan/ direncanakan","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"STRATEGI PELATIHAN"},{"id":154,"number":"12.1.2","title":"Rencana pelatihan K3 bagi semua tingkatan telah disusun.","explanation":"Dapat dilihat pada program pelatihan tahunan perusahaan kemudian komposisi peserta pelatihannya","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"STRATEGI PELATIHAN"},{"id":155,"number":"12.1.3","title":"Jenis pelatihan K3 yang dilakukan harus disesuaikan dengan kebutuhan untuk pengendalian potensi bahaya.","explanation":"Lihat kembali pada matriks pelatihan K3 dengan disesuaikan  job qualification-nya. Perhatikan untuk pelatihan khusus yang dipersyaratkan oleh peraturan perundangan seperti operator forklift, crane, ketel uap, regu kebakaran, sekretrais P2K3, dll.","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"STRATEGI PELATIHAN"},{"id":156,"number":"12.1.4","title":"Pelatihan dilakukan oleh orang atau badan yang berkompeten dan berwenang sesuai peraturan perundang-undangan.","explanation":"Kriteria ini terkait dengan pihak ketiga yang digunakan jasanya untuk mengadakan pelatihan. Ha ini diatur dalam Per.Menaker No.Per.04/MEN/1995 tentang Perusahaan Jasa K3. Penerapan kesesuaian ini dapat dilihat dari kontrak pembelian jasa.","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"STRATEGI PELATIHAN"},{"id":157,"number":"12.1.5","title":"Terdapat fasilitas dan sumber daya memadai untuk pelaksanaan pelatihan yang efektif.","explanation":"Perusahaan menyediakan fasiitas pelatihan dan sumber daya untuk kegiatan pelatihan (khususnya bila pelatihan bersifat internal).","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"STRATEGI PELATIHAN"},{"id":158,"number":"12.1.6","title":"Pengusaha atau pengurus mendokumentasikan dan menyimpan catatan seluruh pelatihan","explanation":"Catatan pelatihan seperti daftar hadir, jadwal, dll disimpan dan diarsipkan (flie) termasuk daftar riwayat pelatihan per pekerja.","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"STRATEGI PELATIHAN"},{"id":159,"number":"12.1.7","title":"Program pelatihan ditinjau secara teratur untuk menjamin agar tetap relevan dan efektif.","explanation":"Setiap selesei perogram pelatihan sebaiknya dibuat lembar evaluasi terhadap pelaksanaan pelatihan","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"STRATEGI PELATIHAN"},{"id":160,"number":"12.2.1","title":"Anggota manajemen eksekutif dan pengurus berperan serta dalam pelatihan yang mencakup penjelasan tentang kewajiban hukum dan prinsip-prinsip serta pelaksanaan K3","explanation":"Manajemen senior terlibat dalam kegiatan pelatihan K3. Terlibat disini termasuk ikut serta dalam pelatihan, minimal pelatihan tentang penjelasan tentang kewajiban hukum dan prinsip-prinsp serta pelaksanaan K3. Dokumen yang dilihat yaitu catatan pelatihan, sertifikat (jika ada) atau kegiatan yang diikuti seperti seminar, dll.","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"PELATIHAN BAGI MANAJEMEN DAN PENYELIA"},{"id":161,"number":"12.2.2","title":"Manajer dan pengawas/penyelia menerima pelatihan yang sesuai dengan peran dan tanggung jawab mereka","explanation":"Pelatihan ini bukan hanya pelatihan K3 yang sesuai dengan peran dan tugasnya namun juga yang berhubungan dengan kompetensi pekerjaannya. Kesesuaiannya dapat dilihat dari job qualificationnya dan atau matriks pelatihan mereka. \nBukti penerapannya dapat dilihat pada rekaman pelatihan dan sertifikat atau daftar riwayat pelatihan mereka.","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"PELATIHAN BAGI MANAJEMEN DAN PENYELIA"},{"id":162,"number":"12.3.1","title":"Pelatihan diberikan kepada semua tenaga kerja termasuk tenaga kerja baru dan yang dipindahkan agar mereka dapat melaksanakan tugasnya secara aman","explanation":"Setiap tenaga kerja baru mendapatkan pelatihan bagaimana bekerja dengan aman termasuk pengenalan mengenai K3, begitu pula dengan tenaga kerja yang dipindahkan ke bagian yang baru. Lihat pada prosedur pelatihan dan catatan pelatihan.","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"PELATIHAN BAGI TENAGA KERJA"},{"id":163,"number":"12.3.2","title":"Pelatihan diberikan kepada tenaga kerja apabila di tempat kerjanya terjadi perubahan sarana produksi atau proses","explanation":"Perubahan sarana produksi atau proses dapat menimbulkan bahaya baru, maka tenaga kerja harus diinformasikan mengenai bahaya tsb.","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"PELATIHAN BAGI TENAGA KERJA"},{"id":164,"number":"12.3.3","title":"Pengusaha atau pengurus memberikan pelatihan penyegaran kepada semua tenaga kerja","explanation":"Pelatihan penyegaran ini tergantung kebutuhan/pesyaratan yang ada, misalnya pelatihan darurat dilakukan setahun sekali, pelatihan P3K, pelatihan penanganan bahan kimia, dll.","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"PELATIHAN BAGI TENAGA KERJA"},{"id":165,"number":"12.4.1","title":"Terdapat prosedur yang menetapkan persyaratan untuk memberikan taklimat\n(briefing) kepada pengunjung dan mitra kerja guna menjamin K3.","explanation":"Ada program pelatihan pengenalan K3 bagi tenaga kerja. lihat pada materi pelatihan, jadwal pelatihan dan absensi pelatihan pengenalan K3.","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"PELATIHAN BAGI TENAGA KERJA"},{"id":166,"number":"12.5.1","title":"Perusahaan mempunyai sistem yang menjamin kepatuhan terhadap persyaratan lisensi atau kualifikasi sesuai dengan peraturan perundangan untuk melaksanakan tugas khusus, melaksanakan pekerjaan atau mengoperasikan peralatan.","explanation":"Perusahaan melakukan identifikasi terhadp kebutuhan pelatihan yang memang dipersyaratkan dalam peraturan perundangan. Lihat pada TNA atau matriks pelatihan yang ada. Beberapa pelatihan tsb yaitu:\n•\tAhli K3 Umum/Kimia/Konstruksi/ Pesawat Uap dan Bejana Tekanan/ Kebakaran–Per.Menaker No.Per.02/ MEN/1992\n•\tDokter pemeriksa – Per. Menaker No.Per.01/ MEN/1976\n•\t Paramedis – Per. Menaker No.Per. 01/MEN/ 1979\n•\tJuru las – Per. Menaker No. Per.02/ MEN/1982\n•\tOperator  ketel uap – Per. Menaker No.Per.01/ MEN /1988\n•\tRegu kebakaran – Kep. Menaker No.Kep.186/ MEN/1999\n•\tAhli K3 Kimia dan Petugas K3 Kimia – Kep. Menaker No.Kep.187/ MEN/1999\n•\tPetugas P3K-Per. Menakertrans No.Per.15/VII/2008\n•\tOperator crane – Per. Menaker No. Per.09/VII/ MEN/2010","section":"PENGEMBANGAN KETRAMPILAN DAN KEMAMPUAN","subsection":"PELATIHAN KEAHLIAN KHUSUS"}];
